{
  "name": "@chime-io/plugin-opencode",
  "version": "2.0.0",
  "description": "OpenCode plugin for mobile notifications - Telegram alerts for AI coding sessions",
  "type": "module",
  "main": "./dist/index.cjs",
  "types": "./dist/index.d.cts",
  "exports": {
    ".": {
      "types": "./dist/index.d.cts",
      "default": "./dist/index.cjs"
    },
    "./format": {
      "types": "./dist/format.d.cts",
      "default": "./dist/format.cjs"
    },
    "./notifier-plugin": {
      "types": "./dist/notifier-plugin.d.cts",
      "default": "./dist/notifier-plugin.cjs"
    }
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "telegram",
    "notification",
    "ai-coding",
    "developer-tools",
    "mobile-notification",
    "claude-code",
    "plugin"
  ],
  "homepage": "https://github.com/yourusername/telnotify#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/yourusername/telnotify.git",
    "directory": "packages/opencode"
  },
  "bugs": {
    "url": "https://github.com/yourusername/telnotify/issues"
  },
  "author": "Chime IO Team",
  "license": "MIT",
  "dependencies": {
    "@chime-io/core": "2.0.0",
    "@chime-io/channel-telegram": "2.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@types/node": "~25.5.2",
    "tsup": "~8.4.0",
    "tsx": "~4.21.0",
    "typescript": "^5.8.3"
  },
  "scripts": {
    "build": "tsup",
    "build:watch": "tsup --watch",
    "test": "tsx --test src/test/**/*.test.ts",
    "clean": "rm -rf dist",
    "typecheck": "tsc --noEmit --pretty false"
  }
}
